<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { aihotFeedState, type AiHotFeedArticle } from '../aihot/aihot-feed-store';
import { DEFAULT_AIHOT_API } from '../services/aihot.service';
const props=defineProps<{selected:AiHotFeedArticle[];disabled?:boolean}>();
const emit=defineEmits<{close:[];select:[article:AiHotFeedArticle];dragStart:[article:AiHotFeedArticle];dragEnd:[]}>();
const articles=ref<AiHotFeedArticle[]>([...aihotFeedState.feedArticles]),loading=ref(false),error=ref(''),query=ref(''),category=ref('');let controller:AbortController|null=null;
const categories=computed(()=>[...new Set(articles.value.map(article=>article.category).filter((value):value is string=>Boolean(value)))]);
const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return articles.value.filter(item=>(!category.value||item.category===category.value)&&(!q||`${item.title} ${item.summary||''}`.toLowerCase().includes(q)));});
function isSelected(article:AiHotFeedArticle){return props.selected.some(item=>item.url===article.url&&item.title===article.title);}
function drag(event:DragEvent,article:AiHotFeedArticle){if(props.disabled){event.preventDefault();return;}event.dataTransfer?.setData('application/x-tab-project-article','article');if(event.dataTransfer)event.dataTransfer.effectAllowed='copy';emit('dragStart',article);}
async function load(){controller?.abort();const request=new AbortController();controller=request;loading.value=true;error.value='';const timer=setTimeout(()=>request.abort(),15000);try{const params=new URLSearchParams({mode:'selected',window:'24h',limit:'30'});const res=await fetch(`${DEFAULT_AIHOT_API}/items?${params}`,{headers:{Accept:'application/json'},signal:request.signal});if(!res.ok)throw new Error(`HTTP ${res.status}`);const data=await res.json();const list=Array.isArray(data?.items)?data.items:Array.isArray(data?.data)?data.data:Array.isArray(data)?data:null;if(!list)throw new Error('资讯响应格式不匹配');if(request!==controller)return;articles.value=list.filter((it:any)=>it&&typeof it==='object').map((it:any):AiHotFeedArticle=>{let published=it.published||'最新';if(it.publishedAt){const d=new Date(it.publishedAt);if(Number.isFinite(d.getTime()))published=`${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}return{id:String(it.id||it.externalId||''),title:it.title||it.headline||'无标题',summary:it.summary||it.description||'',sourceName:it.source?.name||it.sourceName||it.site||'AI 资讯',published,category:it.category||'综合',url:it.links?.aihot||it.links?.original||it.url||it.link||''};});}catch(e){if(request===controller)error.value=request.signal.aborted?'读取超时，请刷新重试。':`读取失败：${e instanceof Error?e.message:'网络异常'}`;}finally{clearTimeout(timer);if(request===controller){loading.value=false;controller=null;}}}
onMounted(()=>void load());onBeforeUnmount(()=>{controller?.abort();controller=null;emit('dragEnd');});
</script>
<template>
 <section class="article-browser" aria-label="AI Hot 文章"><header><div><strong>AI Hot 资讯</strong><small>点击添加或拖到上方输入框 · 最近 24 小时</small></div><div><button type="button" :disabled="loading" @click="load">↻ 刷新</button><button type="button" aria-label="关闭资源浏览" @click="emit('close')">✕</button></div></header><div class="layout"><nav aria-label="资讯分类"><small>资讯分类</small><button type="button" :class="{active:!category}" @click="category=''">全部资讯</button><button v-for="item in categories" :key="item" type="button" :class="{active:category===item}" @click="category=item">{{ item }}</button></nav><main><div class="toolbar"><strong>{{ category||'精选资讯' }}</strong><input v-model="query" type="search" placeholder="搜索已加载资讯" aria-label="筛选资讯" /></div><p v-if="loading&&!articles.length" class="hint">正在读取文章…</p><p v-if="error" class="hint" role="alert">{{ error }}<template v-if="articles.length"> 当前显示已有数据。</template></p><p v-if="!loading&&!error&&!filtered.length" class="hint">暂无匹配文章。</p><div class="grid"><article v-for="(article,index) in filtered" :key="`${article.id}-${index}`" class="article" :class="{selected:isSelected(article)}" :draggable="!disabled" @dragstart="drag($event,article)" @dragend="emit('dragEnd')"><strong>{{ article.title }}</strong><p>{{ article.summary }}</p><div class="meta">{{ article.sourceName }} · {{ article.published }}</div><button type="button" :disabled="disabled" @click="emit('select',article)">{{ isSelected(article)?'✓ 已添加':'＋ 添加' }}</button></article></div></main></div><footer>文章元信息会随消息发送，请检查敏感内容。</footer></section>
</template>
<style scoped>
.article-browser{flex:1;min-height:260px;display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--border,#e2e8f0);border-radius:12px;background:var(--panel,#fff);color:var(--text,#26334b)}header{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--border,#e2e8f0)}header strong,header small{display:block}header strong{font-size:13px}header small{margin-top:3px;color:var(--muted,#94a3b8);font-size:10px}header button{margin-left:5px;border:1px solid var(--border,#e2e8f0);border-radius:7px;padding:5px 9px;background:var(--surface,#f8fafc);color:var(--text,#334155);cursor:pointer;font:inherit;font-size:11px}.layout{display:grid;grid-template-columns:190px minmax(0,1fr);flex:1;min-height:0}nav{overflow:auto;padding:12px 8px;border-right:1px solid var(--border,#e2e8f0)}nav small{display:block;padding:4px 8px;color:var(--muted,#94a3b8);font-size:10px}nav button{width:100%;padding:9px 8px;border:0;border-radius:7px;background:transparent;color:var(--text,#334155);text-align:left;cursor:pointer;font:inherit;font-size:11px}nav button:hover{background:var(--surface,#f1f5f9)}nav button.active{background:rgba(111,103,232,.12);color:#7569ec}main{min-width:0;overflow:auto;padding:14px}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.toolbar strong{font-size:12px}.toolbar input{width:min(220px,50%);padding:7px 9px;border:1px solid var(--border,#e2e8f0);border-radius:7px;background:var(--surface,#f8fafc);color:var(--text,#334155);font:inherit;font-size:11px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,200px),1fr));gap:12px}.article{display:flex;flex-direction:column;min-height:150px;padding:12px;border:1px solid var(--border,#e2e8f0);border-radius:9px;background:var(--surface,#f8fafc);cursor:grab}.article.selected{border-color:#91c9ed}.article strong{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:11px;line-height:1.5}.article p{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;color:var(--muted,#64748b);font-size:10px;line-height:1.5}.meta{margin-top:auto;color:var(--muted,#94a3b8);font-size:10px}.article button{align-self:flex-start;margin-top:7px;padding:5px 8px;border:1px solid var(--border,#e2e8f0);border-radius:6px;background:var(--panel,#fff);color:var(--text,#334155);font:inherit;font-size:10px;cursor:pointer}.hint{color:var(--muted,#94a3b8);font-size:11px}footer{padding:8px 14px;border-top:1px solid var(--border,#e2e8f0);color:var(--muted,#94a3b8);font-size:10px}@media(max-width:760px){.layout{grid-template-columns:130px minmax(0,1fr)}header small{display:none}}
</style>
